        """Return the sorted list of uncovered sub-intervals in [lo, hi).

        The result is the complement of this set clipped to the window:
        each (s, e) is a maximal run of points x with ``lo <= x < hi`` that
        the set does not cover, in sorted order. Pure -- the set is
        unchanged. An empty window (lo >= hi) or a fully covered window
        yields [].
        """
        if lo >= hi:
            return []

        uncovered = []
        cur = lo  # left edge of the still-unexamined part of the window
        for s, e in self._intervals:
            if e <= cur:
                # Entirely at or before the frontier: covers nothing new.
                continue
            if s >= hi:
                # Starts at/after the window's end; sorted by start, so no
                # later region can reach the window either: stop.
                break
